import React, { useEffect, useState } from 'react';
import { getFranchises, deleteFranchise, createFranchise } from '../services/api'; // Import API functions

const FranchiseList = () => {
  const [franchises, setFranchises] = useState([]);
  const [editingFranchise, setEditingFranchise] = useState(null);
  const [formData, setFormData] = useState({
    name: '',
    location: '',
    contactNumber: '',
    status: 'active',
  });

  // Fetch franchises when the component loads
  useEffect(() => {
    fetchFranchises();
  }, []);

  const fetchFranchises = async () => {
    try {
      const response = await getFranchises();
      setFranchises(response.data);
    } catch (error) {
      alert('Error fetching franchises: ' + (error.response?.data?.message || error.message));
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this franchise?')) {
      try {
        await deleteFranchise(id);
        alert('Franchise deleted successfully');
        fetchFranchises();
      } catch (error) {
        alert('Error deleting franchise: ' + (error.response?.data?.message || error.message));
      }
    }
  };

  const handleEdit = (franchise) => {
    setEditingFranchise(franchise);
    setFormData({
      name: franchise.name,
      location: franchise.location,
      contactNumber: franchise.contactNumber,
      status: franchise.status,
    });
  };

  const handleCancelEdit = () => {
    setEditingFranchise(null);
    setFormData({
      name: '',
      location: '',
      contactNumber: '',
      status: 'active',
    });
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingFranchise) {
        // Update franchise logic (if API for update exists)
        alert('Update functionality not yet implemented.');
      } else {
        await createFranchise(formData);
        alert('Franchise created successfully!');
        fetchFranchises();
      }
      handleCancelEdit();
    } catch (error) {
      alert('Error submitting form: ' + (error.response?.data?.message || error.message));
    }
  };

  return (
    <div>
      <h1>Franchise Management</h1>

      {/* Franchise Form */}
      <h2>{editingFranchise ? 'Edit Franchise' : 'Create Franchise'}</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="name">Name:</label>
          <input
            id="name"
            name="name"
            value={formData.name}
            onChange={handleChange}
            placeholder="Franchise Name"
            required
          />
        </div>
        <div>
          <label htmlFor="location">Location:</label>
          <input
            id="location"
            name="location"
            value={formData.location}
            onChange={handleChange}
            placeholder="Franchise Location"
            required
          />
        </div>
        <div>
          <label htmlFor="contactNumber">Contact Number:</label>
          <input
            id="contactNumber"
            name="contactNumber"
            value={formData.contactNumber}
            onChange={handleChange}
            placeholder="Contact Number"
            required
          />
        </div>
        <div>
          <label htmlFor="status">Status:</label>
          <select id="status" name="status" value={formData.status} onChange={handleChange}>
            <option value="active">Active</option>
            <option value="inactive">Inactive</option>
          </select>
        </div>
        <button type="submit">{editingFranchise ? 'Update Franchise' : 'Create Franchise'}</button>
        {editingFranchise && <button onClick={handleCancelEdit}>Cancel Edit</button>}
      </form>

      {/* Franchise List */}
      <h2>Franchise List</h2>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Location</th>
            <th>Contact Number</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {franchises.length > 0 ? (
            franchises.map((franchise) => (
              <tr key={franchise._id}>
                <td>{franchise.name}</td>
                <td>{franchise.location}</td>
                <td>{franchise.contactNumber}</td>
                <td>{franchise.status}</td>
                <td>
                  <button onClick={() => handleEdit(franchise)}>Edit</button>
                  <button onClick={() => handleDelete(franchise._id)}>Delete</button>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="5">No franchises available.</td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};

export default FranchiseList;
